 async function updateUser(values){const p=state.profiles.find(p=>p.user_id===uid);if(values.password){if(values.password.length<8)return {error:Error('Use at least eight characters.')};if(p.activation_required){p.activation_password_set_at=now();if(p.activation_email_verified_at){p.activation_required=false;p.activated_at=now();finishSystem('password_activation',uid,'Account activated: password and email verified');}persist();}}return {data:{user:{...p,...(values.email?{new_email:values.email}:{})}}};}
 const memoryFiles=new Map(), fileUrls=new Map();
 function fileDb(){return new Promise((resolve,reject)=>{if(typeof indexedDB==='undefined'){resolve(null);return;}const r=indexedDB.open('copku-demo-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
 async function saveFile(key,file){const db=await fileDb();if(!db){memoryFiles.set(key,file);return;}await new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(file,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});db.close();}
