 const client={from,rpc,functions:{invoke},auth:{getUser:async()=>({data:{user:{id:uid}}}),signOut:async()=>({data:null}),updateUser,resetPasswordForEmail:async()=>({error:Error('Demo only: no email was sent.')})},storage:{from:bucket=>({createSignedUrl:async path=>{if(['portal-files','portal-notification-files'].includes(bucket)&&path==='__copku_score_demo__/portal-playback-exercise.mscz')return {data:{signedUrl:'/portal/score-preview/demo/portal-playback-exercise.mscz'}};try{const key=bucket+'/'+path,legacy=state.files[key];if(legacy)return {data:{signedUrl:legacy}};if(!fileUrls.has(key)){const file=await readFile(key);if(!file)throw Error('This demo file is unavailable. Attach it again.');fileUrls.set(key,URL.createObjectURL(file));}return {data:{signedUrl:fileUrls.get(key)}};}catch(error){return {error};}},upload:async(path,file)=>{try{const limit=bucket==='portal-images'?3*1024*1024:10*1024*1024;if(!file.size||file.size>limit||(bucket==='portal-images'&&file.size===limit))throw Error('The attachment must be no larger than '+limit/(1024*1024)+' MB.');await saveFile(bucket+'/'+path,file);return {data:{path}};}catch(error){return {error};}}})}};
